    orientations_at = {}
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 == r2 or abs(r2 - r1) != abs(c2 - c1):
                continue
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            # +1: connector slopes down-right; -1: connector slopes down-left.
            orientation = 1 if dr == dc else -1
            for k in range(abs(r2 - r1) + 1):
                p = (r1 + k * dr, c1 + k * dc)
                connector.add(p)
                orientations_at.setdefault(p, set()).add(orientation)
                if grid[p[0]][p[1]] != 6:
                    out[p[0]][p[1]] = 1

    # Each 6 on a connector draws a full diagonal perpendicular to it.
    for r, c in sixes:
        for orientation in orientations_at.get((r, c), ()):
            for rr in range(h):
                if orientation == -1:  # connector slopes down-left; draw down-right
                    cc = rr + (c - r)
                else:                  # connector slopes down-right; draw down-left
                    cc = (r + c) - rr
                if 0 <= cc < w and grid[rr][cc] != 1 and (rr, cc) not in connector:
                    out[rr][cc] = 6

    return out
